const { Client: PgClient } = require("pg");

async function main() {
  const pg = new PgClient({ connectionString: process.env.POSTGRES_URL });
  await pg.connect();

  const ch = createClient({
    url: process.env.CLICKHOUSE_URL,
  });

  // Create analytics database and events table
  await ch.command({ query: "CREATE DATABASE IF NOT EXISTS analytics" });
  await ch.command({
    query: `
      CREATE TABLE IF NOT EXISTS analytics.product_events (
        event_id String,
        event_ts DateTime64(3, 'UTC'),
        user_id String,
        product_id String,
        event_type LowCardinality(String),
        properties String
      ) ENGINE = MergeTree()
      ORDER BY (product_id, event_type, event_ts)
    `,
  });

  // Extract from Postgres
  const { rows } = await pg.query(
    "SELECT event_id, event_ts, user_id, product_id, event_type, properties::text FROM raw.product_events"
  );

  // Insert into ClickHouse
  await ch.insert({
    table: "analytics.product_events",
    values: rows.map((r) => ({
      event_id: r.event_id,
      event_ts: new Date(r.event_ts).toISOString().replace("T", " ").replace("Z", ""),
      user_id: r.user_id,
      product_id: r.product_id,
      event_type: r.event_type,
      properties: r.properties,
    })),
    format: "JSONEachRow",
  });

  // Create materialized views / tables for aggregations
  await ch.command({
    query: `
      CREATE TABLE IF NOT EXISTS analytics.top_products (
        product_id String,
        views UInt64,
        carts UInt64,
        purchases UInt64,
        revenue Float64
      ) ENGINE = SummingMergeTree()
      ORDER BY product_id
    `,
  });

  await ch.command({
    query: `TRUNCATE TABLE IF EXISTS analytics.top_products`,
  });

  await ch.command({
    query: `
      INSERT INTO analytics.top_products
      SELECT
        product_id,
        countIf(event_type = 'view') AS views,
        countIf(event_type = 'cart') AS carts,
        countIf(event_type = 'purchase') AS purchases,
        sumIf(JSONExtractFloat(properties, 'price'), event_type = 'purchase') AS revenue
      FROM analytics.product_events
      GROUP BY product_id
    `,
  });

  await ch.command({
    query: `
      CREATE TABLE IF NOT EXISTS analytics.conversion_funnel (
        step LowCardinality(String),
        unique_users UInt64
      ) ENGINE = ReplacingMergeTree()
      ORDER BY step
    `,
  });

  await ch.command({
    query: `TRUNCATE TABLE IF EXISTS analytics.conversion_funnel`,
  });

  await ch.command({
    query: `
      INSERT INTO analytics.conversion_funnel
      SELECT 'view' AS step, uniqExact(user_id) AS unique_users FROM analytics.product_events WHERE event_type = 'view'
      UNION ALL
      SELECT 'cart' AS step, uniqExact(user_id) AS unique_users FROM analytics.product_events WHERE event_type = 'cart'
      UNION ALL
      SELECT 'purchase' AS step, uniqExact(user_id) AS unique_users FROM analytics.product_events WHERE event_type = 'purchase'
    `,
  });

  await ch.command({
    query: `
      CREATE TABLE IF NOT EXISTS analytics.hourly_activity (
        hour DateTime,
        event_type LowCardinality(String),
        event_count UInt64
      ) ENGINE = SummingMergeTree()
      ORDER BY (hour, event_type)
    `,
  });

  await ch.command({
    query: `TRUNCATE TABLE IF EXISTS analytics.hourly_activity`,
  });

  await ch.command({
    query: `
      INSERT INTO analytics.hourly_activity
      SELECT
        toStartOfHour(event_ts) AS hour,
        event_type,
        count() AS event_count
      FROM analytics.product_events
      GROUP BY hour, event_type
    `,
  });

  // Verify
  const countResult = await ch.query({ query: "SELECT count() AS n FROM analytics.product_events", format: "JSONEachRow" });
  const count = await countResult.json();
  console.log(`Ingested ${count[0].n} events into ClickHouse`);

  await pg.end();
  await ch.close();
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});

